/**
 * A file sealed once by stored-file-cipher.ts under the pinned sodium-native,
 * and committed.
 *
 * Every stored file is held in this format for as long as the instance holds
 * it, so a later build has to open what an earlier one wrote. A library upgrade
 * that cannot fails the test that opens this, instead of every stored file.
 *
 * Two chunks: a full one tagged as a message, then a final one of 100 bytes.
 */

/** The length of the plaintext: one full chunk and 100 bytes. */
export const SEALED_FIXTURE_PLAINTEXT_BYTES = 65_636;

/** The plaintext, computed rather than committed. */
export function sealedFixturePlaintext(): Buffer {
  const bytes = Buffer.alloc(SEALED_FIXTURE_PLAINTEXT_BYTES);
  for (let index = 0; index < bytes.length; index += 1) {
    bytes[index] = (index * 7 + (index >>> 8)) & 0xff;
  }
  return bytes;
}

/** The file's key, hex encoded. */
export const SEALED_FIXTURE_KEY =
  "c131b2283c1df11af18c09044710f23d18769a80458f6f64840c968e1fd8e2cd";

/** The sealed object, base64 encoded: 65 694 bytes. */
export const SEALED_FIXTURE =
  "";
